      "data" : {
        "clauses" : [ {
          "id" : "W-1",
          "revision" : "1",
          "text" : "During the certificate period, covered manufacturing defects qualify for the listed replacement parts and associated standard repair labor"
        }, {
          "id" : "W-2",
          "revision" : "1",
          "text" : "A qualified authorized technician must document the defect and its relationship to the incident; an operator report or model hypothesis alone yields pending determination"
        }, {
          "id" : "W-3",
          "revision" : "1",
          "text" : "Confirmed accidental damage, unauthorized modification causing the fault, and ordinary consumable wear are excluded; exclusions require evidence relevant to this incident"
        }, {
          "id" : "W-4",
          "revision" : "1",
          "text" : "Missing maintenance records are an information gap; their absence alone does not trigger warranty review, suspend coverage, or establish an exclusion. Incomplete or disputed incident-specific findings remain subject to W-7"
        }, {
          "id" : "W-5",
          "revision" : "1",
          "text" : "Expedited attendance premiums, loaners, lost production, and unrelated upgrades are excluded from this warranty"
        }, {
          "id" : "W-6",
          "revision" : "1",
          "text" : "Warranty does not extend merely because a part was replaced during the original period; no separate replacement-part warranty is modeled in this draft"
        }, {
          "id" : "W-7",
          "revision" : "1",
          "text" : "Conflicting or incomplete findings produce pending review with a responsible reviewer; do not silently convert pending to covered or denied"
        }, {
          "id" : "S-1",
          "revision" : "1",
          "text" : "Standard service desk hours are weekdays 08:00–17:00 site time; requests submitted in that window receive acknowledgment within two business hours"
        }, {
          "id" : "S-2",
          "revision" : "1",
          "text" : "Standard attendance targets the next business day, subject to dispatch confirmation; this is not a guaranteed repair deadline"
        }, {
          "id" : "S-3",
          "revision" : "1",
          "text" : "For covered assets, diagnosis and travel are included even if the fault remains unresolved. Only actual authorized repair labor and installed parts are chargeable, subject to warranty and the approved cap. Diagnostic investigation is not chargeable repair labor"
        }, {
          "id" : "S-4",
          "revision" : "1",
          "text" : "Expedited same-day attendance may be offered for a $300 premium, subject to availability and authorization. The premium is payable when expedited attendance occurs, even if the fault remains unresolved; neither service agreement nor warranty pays it"
        }, {
          "id" : "S-5",
          "revision" : "1",
          "text" : "An approved service request submitted before quote expiry preserves the quoted prices for its approved scope. Approval alone does not preserve prices. Creating the request asks dispatch to confirm resources; it does not reserve stock or book an appointment. Changes to attendance, repair scope, or the approved cap require renewed approval"
